from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        byb = [[] for _ in range(n + 1)]
        for j, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            byb[b].append((a, j))
        gain = [0] * m
        base = 0
        t1v, t1i, t2v = 0, -1, 0
        for r in range(1, n + 1):
            for v, j in byb[r]:
                if v > t1v:
                    t2v = t1v
                    t1v, t1i = v, j
                elif v > t2v:
                    t2v = v
            base += r - t1v
            if t1i >= 0:
                gain[t1i] += t1v - t2v
        return base + max(gain)

