    N=A*B-1
    cnt=0
    for p in itertools.permutations(range(1,N+1)):
        if lis(p)!=A or lis([-x for x in p])!=B: continue
        for n in range(0,N+1):
            q=list(p)+[n+0.5]
            if lis(q)==A and lis([-x for x in q])==B:
                cnt+=1
                break
    print(cnt%M)
