def brute(N,M,boxes):
    @functools.lru_cache(None)
    def f(unb, R):
        best=None
        for t in range(M):
            opts=[0]
            if R[t]>0:
                R2=list(R); R2[t]-=1
                opts.append(1+f(unb,tuple(sorted(R2))))
            for i in unb:
                V,P=boxes[i]
                R2=list(R); R2[t]+=V-1
                opts.append(1-P+f(unb-{i},tuple(sorted(R2))))
            v=max(opts)
            best=v if best is None else min(best,v)
        return best
    return f(frozenset(range(N)), tuple([0]*M))
