def hyp(N,M,boxes):
    best=0
    for k in range(1,N+1):
        for S in itertools.combinations(boxes,k):
            if k<M: continue
            rooms=sorted([V-1 for V,P in S],reverse=True)
            val=sum(V-P for V,P in S)-sum(rooms[:M-1])
            best=max(best,val)
    return best
