def solve(N,M,boxes):
    if N<M: return 0
    a=[V-P for V,P in boxes]; b=[1-P for V,P in boxes]
    g=[b[i]-max(a[i],0) for i in range(N)]
    order=sorted(range(N),key=lambda i:-g[i])
    T=order[:M-1]; rest=order[M-1:]
    sb=sum(b[i] for i in T)
    if any(a[i]>0 for i in rest):
        best=sb+sum(max(a[i],0) for i in rest)
    else:
        best=None
        for j in rest:
            others=sorted((i for i in range(N) if i!=j),key=lambda i:-b[i])[:M-1]
            c=sum(b[i] for i in others)+a[j]
            if best is None or c>best: best=c
    return max(0,best)
