class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        N = L + 2
        C = [[0] * (N + 1) for _ in range(N + 1)]
        for i in range(N + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        pc = lambda x: bin(x).count('1')
        steps = [0] * (N + 1)
        for c in range(2, N + 1):
            steps[c] = 1 + steps[pc(c)]
        good = [c for c in range(1, N + 1) if steps[c] <= k - 1]
        cnt = [0] * (N + 1)
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = L - i - 1
                for j in range(rem + 1):
                    cnt[ones + j] = (cnt[ones + j] + C[rem][j]) % MOD
                ones += 1
        ans = 0
        for c in good:
            if c <= N:
                ans += cnt[c]
        return ans % MOD

