def main():
    data=sys.stdin.read().split()
    N=int(data[0]); G=data[1:1+N]
    INF=float('inf')
    inE=[[[] for _ in range(26)] for _ in range(N)]
    outE=[[] for _ in range(N)]
    for u in range(N):
        for v in range(N):
            ch=G[u][v]
            if ch!='-':
                c=ord(ch)-97
                inE[v][c].append(u)
                outE[u].append((v,c))
    NN=N*N
    best=[INF]*(NN+NN*26)
    heap=[]
    for u in range(N):
        for v in range(N):
            val=None
            if u==v: val=0
            elif G[u][v]!='-': val=1
            if val is not None:
                best[u*N+v]=val
                heap.append((val,u*N+v))
    heapq.heapify(heap)
    while heap:
        d,y=heapq.heappop(heap)
        if d>best[y]: continue
        if y<NN:
            a,b=divmod(y,N)
            for v,c in outE[b]:
                x=NN+(a*N+v)*26+c
                if d+1<best[x]:
                    best[x]=d+1; heapq.heappush(heap,(d+1,x))
        else:
            k=y-NN
            ac,c=divmod(k,26)
            a,v=divmod(ac,N)
            for u in inE[a][c]:
                x=u*N+v
                if d+1<best[x]:
                    best[x]=d+1; heapq.heappush(heap,(d+1,x))
    out=[]
    for i in range(N):
        row=[]
        for j in range(N):
            r=best[i*N+j]
            row.append(str(r) if r!=INF else "-1")
        out.append(" ".join(row))
    print("\n".join(out))
