                for j in cols:
                    v = grid[i][j]
                    if v == 1:
                        f[i][j] = 1
                    else:
                        pi, pj = i-di, j-dj
                        if 0 <= pi < n and 0 <= pj < m and f[pi][pj] > 0 and nxt(grid[pi][pj]) == v:
                            f[i][j] = f[pi][pj] + 1
            rows = range(n-1, -1, -1) if di == 1 else range(n)
            cols = range(m-1, -1, -1) if dj == 1 else range(m)
            for i in rows:
                for j in cols:
                    v = grid[i][j]
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == nxt(v):
                        g[i][j] = 1 + g[ni][nj]
            F.append(f)
            G.append(g)
        ans = 0
        for i in range(n):
            for j in range(m):
                for d in range(4):
                    a = F[d][i][j]
                    if a == 0:
                        continue
                    if a > ans:
                        ans = a
                    d2 = (d+1) % 4
                    b = G[d2][i][j]
                    if a + b - 1 > ans:
                        ans = a + b - 1
        return ans

