from typing import List
from functools import lru_cache

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(None)
        def f(o, e, p):
            # p = parity of last placed element: 1 odd, 0 even
            if o + e == 0:
                return 1
            if p == 1:
                return e * f(o, e - 1, 0) if e > 0 else 0
            return o * f(o - 1, e, 1) if o > 0 else 0

        rem = list(range(1, n + 1))
        res = []
        prev = None
        while rem:
            chosen = False
            for idx, v in enumerate(rem):
                if prev is not None and (v % 2) == prev:
                    continue
                o = sum(1 for x in rem if x % 2 == 1) - (v % 2 == 1)
                e = sum(1 for x in rem if x % 2 == 0) - (v % 2 == 0)
                c = f(o, e, v % 2)
                if k <= c:
                    res.append(v)
                    rem.pop(idx)
                    prev = v % 2
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

