class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n
        def f(t):
            return (t - 1) * t * (t + 1) // 6
        D = (f(m) * n * n + f(n) * m * m) % MOD
        a, b = N - 2, k - 2
        num = 1
        for i in range(a - b + 1, a + 1):
            num = num * i % MOD
        den = 1
        for i in range(1, b + 1):
            den = den * i % MOD
        c = num * pow(den, MOD - 2, MOD) % MOD
        return D * c % MOD

