def brute(n,A,B,C):
    s=sum(1<<i for i in range(n) if A[i]); t=sum(1<<i for i in range(n) if B[i])
    dist={s:0}; pq=[(0,s)]
    while pq:
        d,u=heapq.heappop(pq)
        if d>dist.get(u,1e18): continue
        if u==t: return d
        for i in range(n):
            v=u^(1<<i); w=sum(C[k] for k in range(n) if v>>k&1)
