def hyp(n,A,B,C):
    best=None
    ones=[i for i in range(n) if A[i]]
    for r in range(len(ones)+1):
        for X in itertools.combinations(ones,r):
            if any(B[i]==1 for i in X) and False: pass
            if any(A[i]==1 and B[i]==0 and i not in X for i in ones): continue
            W=sum(C[i] for i in ones); total=0
            for c in sorted([C[i] for i in X],reverse=True):
                W-=c; total+=W
            w=W
            Y=[i for i in range(n) if B[i] and (not A[i] or i in X)]
            for c in sorted(C[i] for i in Y):
                w+=c; total+=w
            if best is None or total<best: best=total
    return best
