class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = [0] * h
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w[i] = pow(10, i, k) % k
            else:
                w[i] = (pow(10, i, k) + pow(10, j, k)) % k
        good = [None] * (h + 1)
        good[h] = [False] * k
        good[h][0] = True
        for i in range(h - 1, -1, -1):
            lo = 1 if i == 0 else 0
            cur = [False] * k
            nxt = good[i + 1]
            for r in range(k):
                for d in range(lo, 10):
                    if nxt[(r - d * w[i]) % k]:
                        cur[r] = True
                        break
            good[i] = cur
        if not good[0][0]:
