    F=[int(x) for x in data[2:2+N]]
    p=2+N
    edges=[]
    for i in range(H):
        for j in range(W):
            a=i*W+j
            if j+1<W:
                b=a+1; edges.append((min(F[a],F[b]),a,b))
            if i+1<H:
                b=a+W; edges.append((min(F[a],F[b]),a,b))
    edges.sort(reverse=True)
    parent=list(range(N)); size=[1]*N; pw=[0]*N
    def find(x):
        while parent[x]!=x: x=parent[x]
        return x
    for w,a,b in edges:
        ra=find(a); rb=find(b)
        if ra==rb: continue
        if size[ra]>size[rb]: ra,rb=rb,ra
        parent[ra]=rb; size[rb]+=size[ra]; pw[ra]=w
    INF=float('inf')
    Q=int(data[p]); p+=1
    out=[]
    for _ in range(Q):
        A,B_,Y,C,D,Z=(int(x) for x in data[p:p+6]); p+=6
        u=(A-1)*W+(B_-1); v=(C-1)*W+(D-1)
