        def occ(pat, text):
            n = len(text)
            if not pat:
                return list(range(n + 1))
            m = len(pat)
            f = [0] * m
            k = 0
            for i in range(1, m):
                while k and pat[i] != pat[k]:
                    k = f[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                f[i] = k
            res = []
            k = 0
            for i, c in enumerate(text):
                while k and c != pat[k]:
                    k = f[k - 1]
                if c == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = f[k - 1]
            return res
        i = p.index('*')
        j = p.index('*', i + 1)
        pre = p[:i]
        mid = p[i + 1:j]
        suf = p[j + 1:]
