from collections import deque
def bfs_all(N):
    res={}
    for a in range(1,1<<N):
        dist={a:0}; q=deque([a])
        while q:
            m=q.popleft()
            for c in range(N):
                nm=0
                for j in range(N):
                    if m>>j&1:
                        nj = j+1 if c>j else (j-1 if c<j else j)
                        nm|=1<<nj
                if nm not in dist:
                    dist[nm]=dist[m]+1; q.append(nm)
        res[a]=dist
    return res
