import sys, random
def solve(K, S, T):
    n, m = len(S), len(T)
    if abs(n - m) > K:
        return False
    M = (1 << 61) - 1
    B = random.randrange(10**6, 10**9)
    pw = [1] * (max(n, m) + 1)
    for i in range(1, len(pw)):
        pw[i] = pw[i-1] * B % M
    hS = [0] * (n + 1)
    for i, c in enumerate(S):
        hS[i+1] = (hS[i] * B + ord(c)) % M
    hT = [0] * (m + 1)
    for i, c in enumerate(T):
        hT[i+1] = (hT[i] * B + ord(c)) % M
    def slide(x, y):
        hi = min(n - x, m - y)
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            a = (hS[x+mid] - hS[x] * pw[mid]) % M
            b = (hT[y+mid] - hT[y] * pw[mid]) % M
            if a == b:
                lo = mid
            else:
                hi = mid - 1
        return x + lo
    NEG = -10**18
    target = n - m
    prev = {0: slide(0, 0)}
    if prev[0] >= n and target == 0:
        return True
    for e in range(1, K + 1):
        cur = {}
        for d in range(-e, e + 1):
            best = NEG
            if d in prev:
                best = max(best, prev[d] + 1)
            if d - 1 in prev:
                best = max(best, prev[d-1] + 1)
            if d + 1 in prev:
                best = max(best, prev[d+1])
            if best == NEG:
                continue
            x = min(best, n, m + d)
            y = x - d
            if x < 0 or y < 0:
                continue
            x = slide(x, y)
            cur[d] = x
        prev = cur
        if target in prev and prev[target] >= n:
            return True
    return False

