from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        pre = []
        stack = [0]
        while stack:
            x = stack.pop()
            pre.append(x)
            for y in children[x]:
                stack.append(y)
        post = pre[::-1]
        pos = [0] * n
        for idx, x in enumerate(post):
            pos[x] = idx
        size = [1] * n
        for x in post:
            if parent[x] != -1:
                size[parent[x]] += size[x]
        chars = [s[x] for x in post]
        m = 2 * n + 1
        t = ['#'] * m
        for i in range(n):
            t[2 * i + 1] = chars[i]
        p = [0] * m
        c = r = 0
        for i in range(m):
            if i < r:
                k = min(r - i, p[2 * c - i])
            else:
                k = 0
            while i - k - 1 >= 0 and i + k + 1 < m and t[i - k - 1] == t[i + k + 1]:
                k += 1
            p[i] = k
            if i + k > r:
                c = i
                r = i + k
        ans = [False] * n
        for x in range(n):
            L = size[x]
            hi = pos[x]
            lo = hi - L + 1
            ctr = lo + hi + 1
            ans[x] = p[ctr] >= L
        return ans

