from typing import List
class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = float('inf')
        minp = [INF] * k
        P = 0
        minp[0] = 0
        best = -INF
        for i, x in enumerate(nums, 1):
            P += x
            r = i % k
            if minp[r] != INF:
                c = P - minp[r]
                if c > best:
                    best = c
            if P < minp[r]:
                minp[r] = P
        return int(best)

