class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 10**9 + 7
        f = [1] * 26
        for _ in range(t):
            g = [0] * 26
            for c in range(25):
                g[c] = f[c + 1]
            g[25] = (f[0] + f[1]) % MOD
            f = g
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1
        return sum(cnt[c] * f[c] for c in range(26)) % MOD

