import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True] * N
        sieve[0] = sieve[1] = False
        for i in range(2, 100):
            if sieve[i]:
                for j in range(i * i, N, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        k = len(str(n))
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist.get(v):
                continue
            if v == m:
                return d
            p = 10 ** (k - 1)
            for i in range(k):
                digit = (v // p) % 10
                for nd in (digit - 1, digit + 1):
                    if 0 <= nd <= 9:
                        w = v + (nd - digit) * p
                        if sieve[w]:
                            continue
                        nd2 = d + w
                        if nd2 < dist.get(w, float('inf')):
                            dist[w] = nd2
                            heapq.heappush(pq, (nd2, w))
                p //= 10
        return -1

