import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        radj = [[] for _ in range(n)]
        for a, b, w in edges:
            radj[b].append((a, w))
        INF = float('inf')
        d = [INF] * n
        d[0] = 0
        pq = [(0, 0)]
        while pq:
            dv, v = heapq.heappop(pq)
            if dv != d[v]:
                continue
            for u, w in radj[v]:
                nd = dv if dv > w else w
                if nd < d[u]:
                    d[u] = nd
                    heapq.heappush(pq, (nd, u))
        if any(x == INF for x in d):
            return -1
        return max(d)

