class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = set((x, y) for x, y in points)
        best = -1
        n = len(points)
        for i in range(n):
            for j in range(n):
                x1, y1 = points[i]
                x2, y2 = points[j]
                if not (x1 < x2 and y1 < y2):
                    continue
                if (x1, y2) not in pts or (x2, y1) not in pts:
                    continue
                ok = True
                for x, y in pts:
                    if x1 <= x <= x2 and y1 <= y <= y2:
                        if (x, y) not in ((x1, y1), (x1, y2), (x2, y1), (x2, y2)):
                            ok = False
                            break
                if ok:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

