from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo = -10**19
        hi = 10**19
        o0 = original[0]
        for i in range(len(original)):
            off = original[i] - o0
            u, v = bounds[i]
            lo = max(lo, u - off)
            hi = min(hi, v - off)
        return max(0, hi - lo + 1)

